// ── 🏯 mundo-santuario-zen · Director de Escena & Atmósfera ─────────────────────────────
//
// Configura automáticamente la atmósfera visual, reflejos en agua en tiempo real,
// partículas de luciérnagas/sakura y menú de control OSD para grabación cinemática.
//

// 1. Cargar librerías del ecosistema
await game.snippet("ambientes");
const E = await game.snippet("efectos-demo");

// 2. Configuración estética inicial: Atardecer místico sobre el lago
game.entorno("ATARDECER", 0);
game.reflejoEntorno = true;
game.reflejoOndas = true;
game.reflejoPlanoY = 10.0; // Nivel de la superficie del agua

// 3. Encender partículas de luciérnagas / brasas flotantes
if (E && E.estrellas) {
  E.estrellas.grosor = 4;
  E.estrellas.altura = 12;
  E.estrellas.radio = 45;
  E.estrellas.enciende();
}

// 4. Mandos del Director y Cámara Cinemática
let cineRAF = null;
let cineActivo = false;
let cineYaw = 0;

function toggleCamaraOrbital() {
  cineActivo = !cineActivo;
  if (!cineActivo) {
    if (cineRAF) cancelAnimationFrame(cineRAF);
    toast("🎥 Cámara libre restaurada");
    return;
  }
  toast("🎥 Cámara cinemática activa (WASD para cancelar)");
  const centro = [48, 16, 48];
  const radio = 34;
  const t0 = performance.now();

  function paso() {
    if (!cineActivo) return;
    const t = (performance.now() - t0) * 0.0002;
    mc.pos[0] = centro[0] + Math.cos(t) * radio;
    mc.pos[1] = 18 + Math.sin(t * 0.5) * 3;
    mc.pos[2] = centro[2] + Math.sin(t) * radio;
    // Mirar al centro del santuario
    const dx = centro[0] - mc.pos[0];
    const dz = centro[2] - mc.pos[2];
    mc.yaw = Math.atan2(-dx, -dz);
    mc.pitch = -0.15;
    cineRAF = requestAnimationFrame(paso);
  }
  paso();
}

// Cancelar cámara orbital al tocar movimiento
window.addEventListener('keydown', (e) => {
  if (['w', 'a', 's', 'd', ' '].includes(e.key.toLowerCase()) && cineActivo) {
    cineActivo = false;
    if (cineRAF) cancelAnimationFrame(cineRAF);
  }
}, { capture: true });

// 5. Menú OSD (Tecla O)
const htmlOSD = () => '<div class="mc-osd-panel">'
  + '<div class="mc-osd-title">🏯 SANTUARIO ZEN</div>'
  + '<button class="mc-osd-btn" data-osd="HORA_ATARDECER">🌅 ATARDECER</button>'
  + '<button class="mc-osd-btn" data-osd="HORA_NOCHE">🌙 NOCHE</button>'
  + '<button class="mc-osd-btn" data-osd="HORA_NIEBLA">🌫️ NIEBLA</button>'
  + '<button class="mc-osd-btn" data-osd="REFLEJOS">✨ REFLEJOS: ' + (game.reflejoEntorno ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="LUCES">🏮 LUCIÉRNAGAS: ' + (E.estrellas._on ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="HOJAS">🌸 HOJAS CEREZO</button>'
  + '<button class="mc-osd-btn" data-osd="ORBITA">🎥 CÁMARA ORBITAL</button>'
  + '<button class="mc-osd-btn" data-osd="REC">🔴 GRABAR VÍDEO (Alt+V)</button>'
  + '<button class="mc-osd-btn">CERRAR</button>'
  + '</div>';

game.osd.define('menu_santuario', { sitio: 'abajo-derecha', showTool: false, html: htmlOSD() });

game.osd.alPulsar('HORA_ATARDECER', () => { game.entorno('ATARDECER', 2); });
game.osd.alPulsar('HORA_NOCHE', () => { game.entorno('NOCHE', 2); });
game.osd.alPulsar('HORA_NIEBLA', () => { game.entorno('NIEBLA', 2); });
game.osd.alPulsar('REFLEJOS', () => {
  game.reflejoEntorno = !game.reflejoEntorno;
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});
game.osd.alPulsar('LUCES', () => {
  if (E.estrellas._on) E.estrellas.apaga(); else E.estrellas.enciende();
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});
game.osd.alPulsar('HOJAS', () => {
  if (E.hojas) E.hojas.salpica([48, 18, 48]);
});
game.osd.alPulsar('ORBITA', () => {
  game.osd.cerrar();
  toggleCamaraOrbital();
});
game.osd.alPulsar('REC', () => {
  game.osd.cerrar();
  if (typeof game.video !== 'undefined') game.video();
});

game.onKey('o', () => {
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});

toast('🏯 Santuario Zen listo · Tecla O para menú de director · F foto · Alt+V vídeo', 6);
